 async function loadExtras(operatorOnly=false){
  if(!detail)return;
  // Bound independent reads to two; publish only after every required read succeeds.
  const order=detail.id,job=jobSelected,next={};
  if(isOperator()&&(page==='operator'||operatorOnly)){
   // Operator screens do not render material, downstream or assignment panels.
   // Keep both histories: completion totals and named quality decisions use them.
   if(job)[next.productionHistory,next.qualityHistory]=await Promise.all([api.readOperation('productionHistory',order,job),api.readOperation('qualityHistory',order,job)]);
   if(job&&jobs.find(x=>x.id===job)?.status==='complete')next.handoff=await api.readOperation('handoff',order,job);
   extras=next;return;
  }
  [next.material,next.downstream]=await Promise.all([api.readOperation('material',order),api.readOperation('downstream',order)]);
  if(job){
   [next.handoff,next.assignment]=await Promise.all([isOperator()?api.readOperation('handoff',order,job):null,capable('orders.write')?api.readOperation('assignment',order,job):null]);
   [next.productionHistory,next.qualityHistory]=await Promise.all([api.readOperation('productionHistory',order,job),api.readOperation('qualityHistory',order,job)]);
  }
  extras=next;
 }
 async function refreshOperatorResult(order,id){
  // Refresh authorization/ownership and jobs together; the order itself was not
  // edited by a production command. Never publish actionable partial results.
  productionView=null;qualityView=null;extras={};
  const [nextJobs]=await Promise.all([api.workOrders(order),refreshAssigned()]);
  if(operatorJobId!==id||!assignedJobs.some(x=>x.id===id))throw Error('İş emri artık size atanmamış.');
  jobs=nextJobs.workOrders;
  try{
   const [production,quality]=await Promise.all([api.production(order,id),api.quality(order,id)]);
   await loadExtras(true);productionView=production;qualityView=quality;
  }catch(e){productionView=null;qualityView=null;extras={};throw e}
 }
 async function loadQualityQueue(){const originScope=scope;qualityQueue=[];qualityQueueErrors=[];for(let i=0;i<jobs.length;i+=8){const batch=jobs.slice(i,i+8);const results=await Promise.allSettled(batch.map(j=>api.quality(j.orderId,j.id)));if(scope!==originScope)return;for(let k=0;k<batch.length;k++){const result=results[k],job=batch[k];if(result.status==='rejected'){qualityQueueErrors.push({job,message:result.reason?.message||'Kalite durumu alınamadı'});continue}for(const output of result.value.outputs||[]){if(!Number.isSafeInteger(output.unresolved)||output.unresolved<0){qualityQueueErrors.push({job,message:'Kalite miktarı doğrulanamadı'});continue}if(output.unresolved>0)qualityQueue.push({job,output})}}}}
