 async function loadDetail(id,includeSummary=true){
  const [nextDetail,nextJobs]=await Promise.all([api.order(id),api.workOrders(id)]);
  let editing=null,summary=null,availability=null;
  if(includeSummary){
   [editing,summary]=await Promise.all([api.orderEditing?api.orderEditing(id):null,api.orderSummary?api.orderSummary(id):null]);
   const op=nextDetail.route.find(x=>x.sequence===0);
   if(op)availability=await api.availability(id,op.id);
  }
  detail=nextDetail;jobs=nextJobs.workOrders;orderEditingView=editing;orderSummary=summary;avail=availability;selected=id;
  if(!orders.some(x=>x.id===id))orders.unshift(detail);
  if(!shippingReady.some(x=>x.id===id))shippingReady.unshift(detail);
 }
