 function capturePo(){if(!poDraft)return;for(const key of ['number','quantity']){const e=el('po-'+key);if(e)poDraft[key]=key==='quantity'?Number(e.value):e.value}poDraft.operations.forEach((op,i)=>{op.name=el('po-name-'+i)?.value??op.name;op.kind=el('po-kind-'+i)?.value??op.kind;for(const [key,suffix]of [['setupMinutes','setup'],['cycleMinutes','cycle']]){const field=el('po-'+suffix+'-'+i);if(field)op[key]=field.value===''?null:Number(field.value)}})}
