 function masterPicker(key,label,placeholder){return `<div class="formfield master-picker"><label for="order-${key}">${label}</label><input class="input" id="order-${key}" data-wiz="${key}" value="${h(wizard[key])}" placeholder="${placeholder}" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="order-${key}-results" aria-describedby="order-${key}-status" autocomplete="off" required><div class="master-picker-results" id="order-${key}-results" role="listbox" aria-label="${label}" hidden></div><span class="master-picker-status" id="order-${key}-status" role="status">${wizard[key+'Id']?'Kayıt seçildi':'Ad veya kod yazarak seçin.'}</span>${capable('master.write')?`<button type="button" class="master-quick-add" onclick="RitimPremiumAPI.quickMaster('${key}','wizard')">+ Yeni ${key==='customer'?'müşteri ekle':'stok kartı ekle'}</button>`:''}</div>`}
 function bindMasterPickers(){for(const key of ['customer','part']){const input=el('order-'+key),list=el('order-'+key+'-results'),status=el('order-'+key+'-status');if(!input||input.disabled)continue;let timer,revision=0,items=[],active=-1;const originScope=scope,originWizard=wizard;const close=()=>{list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1};const choose=index=>{const item=items[index];if(!item)return;input.value=item.name;wizard[key]=item.name;wizard[key+'Id']=item.id;if(key==='part'){wizard.materials=structuredClone(item.materials||[]);wizard.partNo=item.code||'';const code=document.querySelector('[data-wiz="partNo"]');if(code)code.value=wizard.partNo}revision++;clearTimeout(timer);status.textContent='Kayıt seçildi'+(item.code?' · '+item.code:'');close();if(key==='part'){captureWizard();renderModal()}};const search=async()=>{const request=++revision,q=input.value.trim();status.textContent='Aranıyor…';try{const result=await api.masterSearch(key==='customer'?'customers':'parts',q);if(request!==revision||scope!==originScope||wizard!==originWizard||!input.isConnected)return;items=result.items;active=-1;list.innerHTML=items.map((x,i)=>`<div role="option" aria-selected="false" id="order-${key}-option-${i}" data-option="${i}"><b>${h(x.name)}</b><small>${h(x.code||'Kod belirtilmedi')}</small></div>`).join('')||'<div class="master-picker-empty">Kayıt bulunamadı. Tanımlamalar bölümünden ekleyebilirsiniz.</div>';list.hidden=false;input.setAttribute('aria-expanded','true');status.textContent=items.length?`${items.length} sonuç${result.nextAfter?' · Daha fazla sonuç için aramayı daraltın.':''}`:'Eşleşen kayıt yok.'}catch(e){if(request!==revision||!input.isConnected||scope!==originScope)return;close();status.textContent='Kayıtlar alınamadı. Yeniden arayın.'}};input.addEventListener('input',()=>{wizard[key+'Id']=null;wizard[key]=input.value;if(key==='part'){wizard.partNo='';const code=document.querySelector('[data-wiz="partNo"]');if(code)code.value=''}revision++;close();status.textContent='Listeden bir kayıt seçin.';clearTimeout(timer);timer=setTimeout(search,220)});input.addEventListener('focus',()=>{clearTimeout(timer);timer=setTimeout(search,0)});input.addEventListener('blur',()=>{revision++;clearTimeout(timer);close()});list.addEventListener('pointerdown',e=>e.preventDefault());list.addEventListener('click',e=>{const option=e.target.closest('[data-option]');if(option)choose(Number(option.dataset.option))});input.addEventListener('keydown',e=>{if(e.key==='Escape'&&!list.hidden){e.preventDefault();e.stopPropagation();close();return}if(e.key==='Enter'&&!list.hidden&&active>=0){e.preventDefault();choose(active);return}if(!['ArrowDown','ArrowUp'].includes(e.key)||list.hidden||!items.length)return;e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;[...list.querySelectorAll('[role=option]')].forEach((x,i)=>x.setAttribute('aria-selected',String(i===active)));input.setAttribute('aria-activedescendant',`order-${key}-option-${active}`);el(`order-${key}-option-${active}`).scrollIntoView({block:'nearest'})})}}
 async function loadMaster(){if(masterView.kind==='locations'){inventoryView.locations=(await api.inventoryRead('locations')).locations;return true}if(['parts','units'].includes(masterView.kind))await loadStockUnits();if(masterView.kind==='units')return true;if(masterView.kind==='suppliers'){const response=await api.outsourcingSuppliers();supplierTypesSupported=response.supplierTypesSupported===true;outsourcingSuppliers=response.suppliers;return localMasterPage(outsourcingSuppliers)}if(masterView.kind==='shifts'){RitimShiftEditor.set(await api.workCalendar(),capable('planning.write'));return true}if(masterView.kind==='machines'){machineBoard=await readMachineBoard();return localMasterPage(machineBoard.machines)}const version=++masterSearchRevision,originScope=scope;const result=await api.masterPage(masterView.kind,{q:masterView.q,page:masterView.page||1,size:masterView.size||20,sort:masterView.sort||'name',direction:masterView.direction||'asc'});if(version!==masterSearchRevision||scope!==originScope)return false;Object.assign(masterView,result,{nextAfter:null});return true}
