 let monitorMode='list',monitorSearch='';
 function productionMonitorContent(){const t=operationsTemplate(productionMonitorContentOriginal()),root=t.content.firstElementChild;if(!root)return t.innerHTML;root.classList.add('compact-data-page');const q=monitorSearch.toLocaleLowerCase('tr-TR'),sort=listSorts['production-monitor'],rows=monitorJobs.filter(j=>(monitorFilter==='all'||monitorFilter==='running'&&j.status==='running'||monitorFilter==='ready'&&j.ready||monitorFilter==='blocked'&&j.blockers?.length)&&[j.number,j.partName,j.orderNumber,j.customer,j.machineCode,j.operatorName].join(' ').toLocaleLowerCase('tr-TR').includes(q));if(sort)rows.sort((a,b)=>{const x=a[sort.key],y=b[sort.key],n=typeof x==='number'&&typeof y==='number'?x-y:String(x??'').localeCompare(String(y??''),'tr',{numeric:true});return sort.desc?-n:n});const open=j=>j.kind==='external'&&j.productionOrderId?`RitimPremiumAPI.openSupplierJob(${jsArg(j.productionOrderId)},${jsArg(j.id)})`:`RitimPremiumAPI.openJob(${jsArg(j.id)},${jsArg(j.orderId)})`,text=(key,label)=>({key,label,cell:j=>h(j[key]||'—')}),columns=[{key:'number',label:'İş emri',cell:j=>`<button class="grid-link" onclick="${open(j)}">${h(j.number)}</button><small>${h(j.operation)}</small>`},text('partName','Parça'),text('customer','Müşteri'),text('orderNumber','Sipariş'),{key:'orderCreatedAt',label:'Sipariş tarihi',cell:j=>h(workspaceDate(j.orderCreatedAt))},{key:'dueDate',label:'Teslim termini',cell:j=>h(workspaceDate(j.dueDate))},text('machineCode','Makine'),{key:'produced',label:'İşlenen / hedef',cell:j=>`${j.produced} / ${j.quantity}`},{key:'status',label:'Durum',cell:j=>`<span class="pill">${h(poStatus(j.status))}</span><small>${h(j.reason)}</small>`}];const grid=root.querySelector('.flow-job-grid'),html=operationalPage('production-monitor',columns,rows,sort),holder=operationsTemplate(html);if(monitorMode==='cards'){const p=listPaging['production-monitor'],visible=rows.slice((p.page-1)*p.size,p.page*p.size);holder.content.querySelector('.order-grid-section').outerHTML=`<div class="monitor-cards">${visible.map(j=>`<article class="card"><header><span class="pill">${h(poStatus(j.status))}</span><strong>${h(j.operation)}</strong></header><h3>${h(j.partName)}</h3><p class="monitor-customer">${h(j.customer)}</p><button class="grid-link" onclick="RitimPremiumAPI.orderPeek(${jsArg(j.orderId)})">${h(j.orderNumber)}</button><dl><div><dt>Sipariş tarihi</dt><dd>${h(workspaceDate(j.orderCreatedAt))}</dd></div><div><dt>Teslim termini</dt><dd>${h(workspaceDate(j.dueDate))}</dd></div><div><dt>Makine</dt><dd>${h(j.machineCode||'Atanmadı')}</dd></div><div><dt>İşlenen / hedef</dt><dd>${j.produced} / ${j.quantity}</dd></div></dl><progress max="${Math.max(1,j.quantity)}" value="${j.produced}" aria-label="Üretim ilerlemesi"></progress><footer><small>${h(j.reason)}</small><button class="btn" onclick="${open(j)}">İşi aç</button></footer></article>`).join('')||'<p>Eşleşen iş yok.</p>'}</div>`}grid.outerHTML=`<form class="monitor-list-tools" onsubmit="event.preventDefault();RitimPremiumAPI.monitorSearch()"><input class="input" id="monitor-query" type="search" aria-label="Üretimde ara" placeholder="Sipariş, müşteri, parça veya makine" value="${h(monitorSearch)}"><button class="btn" type="submit">Ara</button><button class="btn" type="button" onclick="RitimPremiumAPI.monitorSearch(true)">Temizle</button><button class="btn" type="button" aria-pressed="${monitorMode==='list'}" onclick="RitimPremiumAPI.monitorMode('list')">Liste</button><button class="btn" type="button" aria-pressed="${monitorMode==='cards'}" onclick="RitimPremiumAPI.monitorMode('cards')">Kartlar</button><span>${rows.length} iş</span></form>${holder.innerHTML}`;return t.innerHTML}
