  const rows=list=>'<div class="order-material-lines">'+list.map((x,i)=>'<article><div class="order-material-product"><b>'+(i+1)+' · '+(w.step===1?'<input class="input order-line-qty" type="number" min="1" step="1" aria-label="'+(i+1)+'. ürün adedi" value="'+h(x.quantity)+'" onchange="RitimPremiumAPI.orderItemQuantity('+i+',this.value)">':h(x.quantity))+' adet × '+h(x.partName)+'</b><small>'+h(x.partNumber||'')+' · '+h(workspaceDate(x.dueDate))+'</small></div>'+((x.materials?.length||w.step===1)?'<div class="order-material-summary">'+(x.materials?.length?'<small>Kullanılacak malzemeler</small>':'')+orderMaterialsSummary(x.materials)+(w.step===1?'<button class="workspace-text-link" type="button" onclick="RitimPremiumAPI.orderMaterialsOpen('+i+')">'+(x.materials?.length?'Malzemeleri düzenle':'+ Malzeme ekle')+'</button>':'')+'</div>':'')+(w.step===1?'<button class="btn sm" type="button" onclick="RitimPremiumAPI.removeOrderItem('+i+')">Kaldır</button>':'')+'</article>').join('')+'</div>';

