  return progress+'<section class="order-review"><h3>'+h(w.customer)+'</h3><p>'+items.length+' ürün kalemi · '+h(w.id||'Sipariş numarası kayıtta oluşturulacak')+'</p>'+rows(items)+'<button class="btn" type="button" onclick="wizardNext(1)">Bilgileri düzenle</button></section>';
