 function displayWizard(){const w=wizard;const stage=resume?.steps;const done=stage?.order==='committed'&&['committed','skipped'].includes(stage.route)&&['committed','skipped'].includes(stage.plan);const status=done?`<div class="polish-order-success" role="status"><strong>Sipariş oluşturuldu</strong><p>${h(resume.order.orderNumber)}</p></div>`:stage?`<div class="ux6-alert">${stage.order==='committed'&&['committed','skipped'].includes(stage.route)?'<b>Sipariş başarıyla oluşturuldu.</b><br>':''}Sipariş: ${h(stageLabel(stage.order))} · Rota: ${h(stageLabel(stage.route))} · İş emri: ${h(stageLabel(stage.plan))}<p>Bu adımlar ayrı sunucu işlemleridir.</p></div>`:'';const locked=!!resume&&!correcting;const failed=stage&&['order','route','plan'].find(x=>stage[x]==='failed');const body=resume?.plan&&typeof legacyWizardContent==='function'?legacyWizardContent():wizardContent();const label=w.step===3?(stage?'Sonraki sunucu adımı':'Siparişi Kaydet'):'Devam Et →';el('overlay').innerHTML=`<div class="modal-back wizard-back"><div class="modal wizard-modal order-compose" role="dialog" aria-modal="true" aria-labelledby="order-compose-title"><div class="modal-head"><h2 id="order-compose-title">${h(['','1 / 2 · Sipariş Bilgileri','2 / 3 · Operasyon Rotası','2 / 2 · Siparişi Gözden Geçir'][w.step])}</h2><button class="btn sm" onclick="closeModal()" aria-label="Kapat">×</button></div><div class="modal-body">${status}${body}${''}${error?`<p class="ux6-alert" role="alert">${h(error)}</p>`:''}</div><div class="modal-foot"><button class="btn" onclick="${w.step===1||locked?'closeModal()':`wizardNext(${w.step===3&&!w.route.length?1:w.step-1})`}">${w.step===1||locked?'Kapat':'← Geri'}</button>${correcting?'<button class="btn primary" onclick="RitimPremiumAPI.saveCorrection()">Düzeltmeyi Kaydet</button>':stage&&stage.order==='committed'&&['committed','skipped'].includes(stage.route)&&['committed','skipped'].includes(stage.plan)?'<button class="btn" onclick="RitimPremiumAPI.finish(true)">Üretim Emri Oluştur</button><button class="btn primary" onclick="RitimPremiumAPI.finish()">Siparişe Git</button>':`<button class="btn primary" onclick="${w.step===3?'RitimPremiumAPI.submitWizard()':`wizardNext(${w.step===1?3:w.step+1})`}" ${busy?'disabled':''}>${h(label)}</button>`}${failed&&!correcting?'<button class="btn" onclick="RitimPremiumAPI.correct()">Başarısız adımı düzelt</button>':''}</div></div></div>`;if(locked)el('overlay').querySelectorAll('[data-wiz],.route-row button,.catalog-operation-choice,#newRoute').forEach(x=>x.disabled=true);const machine=el('overlay').querySelector('[data-wiz="machine"]');if(machine)machine.disabled=true;for(const key of ['revision','created','material','dimensions']){const field=el('overlay').querySelector(`[data-wiz="${key}"]`);if(field){field.disabled=true;field.closest('.formfield').hidden=true}}const routeSelect=el('newRoute');if(routeSelect)for(const option of [...routeSelect.options])if(!['İmalat','Tesviye','Kaplama'].includes(option.value))option.remove();syncWizardViewport();bindMasterPickers()}
 function preferredMembership(){
  const memberships=session?.memberships||[];
  if(memberships.length===1)return memberships[0];
  try{const saved=JSON.parse(localStorage.getItem('ritim:last-workspace:v1:'+session.identity.id));return memberships.find(m=>m.tenantId===saved?.tenantId&&m.siteId===saved?.siteId)||null}catch{return null}
 }
 async function activateMembership(m){
  try{
   RitimLegacyRecovery.cleanupBrowser();
   const x=await api.selectScope(m.tenantId,m.siteId);
   await enterScope({scope:{actorId:session.identity.id,tenantId:m.tenantId,siteId:m.siteId,roles:x.roles},caps:x.capabilities});
   try{localStorage.setItem('ritim:last-workspace:v1:'+session.identity.id,JSON.stringify({tenantId:m.tenantId,siteId:m.siteId}))}catch{}
  }catch(e){clearSite();throw e}
 }
 async function restoreMembership(){const m=preferredMembership();if(m)await activateMembership(m)}
 async function initializeAuth(){try{const ref=new URL(document.referrer);if(ref.origin===location.origin&&ref.pathname==='/auth/team'&&!new URLSearchParams(location.search).has('view')){const saved=sessionStorage.getItem('ritim:team-return'),u=new URL(saved||'',location.origin);if(saved&&u.origin===location.origin&&u.pathname==='/'&&u.searchParams.has('view')){history.replaceState({},'',u.pathname+u.search+u.hash)}}}catch{}authLoading=true;draw();try{authProvider=RitimAuthProvider.createBff();const config=await authProvider.config();devToken=requestedDevToken&&config.manualTokenAllowed===true;if(devToken)return;if(!config.enabled)throw Error('OIDC oturumu bu ortamda yapılandırılmamış.');api=RitimApiAdapter.create({cookieSession:true,refreshEnabled:config.refreshEnabled===true,onUnauthorized:()=>{const hadSession=!!session;clearIdentity();error=hadSession?'Oturum sona erdi; yeniden giriş yapın.':''},onScopeDenied:()=>{clearSite();error='İş yeri yetkisi değişti; erişimi yeniden doğrulayın.'}});session=await api.session();try{await restoreMembership()}catch(e){error=e.message}}catch(e){clearIdentity();if(e.status===401&&window.RITIM_CLOUD&&!devToken)location.replace('/auth/login');else if(e.status!==401)error=e.message}finally{authLoading=false;draw()}}
 function rememberListPosition(){if(!scope||!['jobs','production-orders','production-monitor','overview'].includes(page)||new URLSearchParams(location.search).get('view')!==page)return;history.replaceState({...history.state,listPosition:{view:page,scope:scope.actorId+':'+scope.tenantId+':'+scope.siteId,paging:{...listPaging[page]},sort:listSorts[page],y:scrollY,monitorFilter,monitorSearch}},'',location.href)}
 async function restoreListPosition(saved){if(!saved||saved.view!==page||saved.scope!==scope.actorId+':'+scope.tenantId+':'+scope.siteId)return;const size=[20,50,100].includes(saved.paging?.size)?saved.paging.size:20,target=Math.max(1,Number(saved.paging?.page)||1);if(page==='production-monitor'){monitorFilter=saved.monitorFilter||'all';monitorSearch=saved.monitorSearch||''}else{const state=()=>page==='jobs'?worklist:page==='overview'?daily:poList;let v=state();while(v.nextAfter&&(saved.sort||v.items.length<target*size)){const before=v.nextAfter;if(page==='production-orders'){const next=await api.productionOrders(poList.orderId,v.nextAfter,poList.filter);poList.items.push(...next.items);poList.nextAfter=next.nextAfter}else await reloadWorkspace({...workspaceFilters(page),after:v.nextAfter},true);v=state();if(v.nextAfter===before)break}}listPaging[page]={page:target,size};if(saved.sort)listSorts[page]=saved.sort}
 document.addEventListener('click',rememberListPosition,true);
 window.addEventListener('pageshow',event=>{if(event.persisted){if(!session)initializeAuth();else draw()}});
 window.addEventListener('popstate',async event=>{if(!scope)return;const requested=new URLSearchParams(location.search).get('view')||'orders',saved=event.state?.listPosition;if(allowedPage(requested)){saveNavigationDraft();restoreNavigationDraft=true;await run(async()=>{await loadPage(requested);await restoreListPosition(saved)});if(saved?.view===page)scrollTo(0,saved.y||0);else if(requested==='orders')scrollTo(0,ordersScroll)}else{page='orders';error='Bu ekran için yetki yok veya bağlantı geçersiz.';draw()}});

 function machineBoardContent(){return compactMachineBoardContent()}



 function orderRecoveryPanel(){if(!orderRecovery||!orderClosing||orderClosing.orderId!==detail?.id)return '';return `<details class="card pad" id="order-recovery-panel"><summary>Telafi ve sipariş kapatma</summary><h3>Belgelenmiş kayıplar</h3><p>Kaybın tamamı veya bir bölümü için gerekçeli telafi izni oluşturun. Ardından ayrı üretim emriyle planlayın.</p>${orderRecovery.losses.filter(x=>x.available>0).map(x=>`<article class="card pad"><h4>${h(x.label)} · ${x.available} adet kullanılabilir</h4>${capable('quality.write')?`<form class="formgrid" onsubmit="event.preventDefault();RitimPremiumAPI.approveCompensation(${jsArg(x.id)},${jsArg(x.kind)})"><label class="formfield">Telafi adedi<input class="input" type="number" min="1" max="${x.available}" required id="comp-qty-${x.id}" value="${x.available}"></label><label class="formfield">Telafi gerekçesi<input class="input" maxlength="120" required id="comp-reason-${x.id}" placeholder="Kaybın nedenini açıklayın"></label><button class="btn" type="submit">Telafi izni oluştur</button></form>`:''}</article>`).join('')||'<p>Telafiye ayrılabilecek açık kayıp yok.</p>'}${orderRecovery.approvals.map(x=>`<p>Telafi: ${x.quantity} adet · ${h(x.reason)} · Planlanabilir ${x.available}${x.available>0&&capable('planning.write')?`<button class="btn sm" onclick="RitimPremiumAPI.compensationProduction(${jsArg(x.id)},${x.available})">Telafi üretim emri</button>`:''}</p>`).join('')}<h3>Siparişi kapat</h3><p>Net teslimat ${orderClosing.netDelivered} / ${orderClosing.orderedQuantity}</p>${orderClosing.reasons.map(x=>`<p class="closing-reason"><span>• ${h(x)}</span><button class="btn sm" onclick="RitimPremiumAPI.openClosingBlocker(${jsArg(x.includes('sevkiyat')||x.includes('teslimat')?'shipping':x.includes('iade')||x.includes('karantina')?'returns':x.includes('telafi')?'compensations':'production-orders')})">İlgili kayıtları aç</button></p>`).join('')}${capable('orders.write')&&orderClosing.status==='open'?`<button class="btn primary" onclick="RitimPremiumAPI.closeOrder()" ${orderClosing.canClose?'':'disabled'}>Siparişi kapat</button>`:''}</details>`}

 function flowMetric(label,value,detail=''){return `<div class="flow-metric"><span>${h(label)}</span><strong>${h(value)}</strong>${detail?`<small>${h(detail)}</small>`:''}</div>`}
 function nextActionAllowed(target){const permission={'production-create':'planning.write','quality-list':'quality.write',rework:'quality.write',shipping:'shipment.write',inventory:'stock.write',closing:'orders.write'}[target];return !permission||capable(permission)}
 function orderSummaryContentOriginal(){const v=orderSummary;if(!v||v.orderId!==detail?.id)return '<section class="card pad"><p>Sipariş özeti alınamadı. Sayfayı yenileyin.</p></section>';const closed=v.status==='closed',inactive=v.status!=='open',canAct=nextActionAllowed(v.next.target);return `<section class="card pad flow-order-summary"><div class="flow-heading"><div><span class="flow-eyebrow">SİPARİŞ ÖZETİ</span><h2>${h(detail.orderNumber)} · ${h(detail.partName)}</h2><p>${h(detail.customer)} · Termin ${h(detail.dueDate||'Belirlenmedi')}</p></div><span class="pill ${closed?'flow-complete':''}">${closed?'Kapalı':inactive?'İptal edildi':'Açık'}</span></div><div class="flow-metrics">${flowMetric('Sipariş',v.orderedQuantity,'adet')}${flowMetric('Üretime ayrılmamış',v.unallocatedQuantity,'Normal sipariş miktarı')}${flowMetric('Telafi üretimi',v.compensationQuantity,'Sipariş miktarına eklenmez')}${flowMetric('Sevke uygun',v.shipping.availableToShip,'Kalite onaylı ve kullanılabilir')}${flowMetric('Sevk edilen',v.shipping.dispatched,'Teslimat ayrıca doğrulanır')}${flowMetric('Net teslim',v.shipping.netDelivered+' / '+v.orderedQuantity,'Fiziksel iadeler düşülür')}</div><div class="flow-next"><div><b>${closed?'Sipariş tamamlandı':inactive?'Sipariş iptal edildi':'Sonraki işlem'}</b><p>${h(v.next.label)}</p></div>${!inactive?`<button class="btn primary" onclick="RitimPremiumAPI.orderNext()">${canAct?'İşleme git →':'Üretimi takip et'}</button>`:''}<button class="btn" onclick="RitimPremiumAPI.poListOrder(${jsArg(detail.id)})">Bağlı Üretim Emirleri</button></div><details class="flow-details"><summary>Miktarlar ve üretim akışı</summary><p>Kalite kararı bekleyen: ${v.qualityPending} işlem adedi · Tamir bekleyen: ${v.repairPending} adet · Fiziksel iade: ${v.shipping.returned} adet · Yolda: ${v.shipping.inTransit} adet</p><p class="tiny">Kalite bekleyen işlem adetleri farklı operasyonları kapsayabilir; sipariş ilerlemesi olarak toplanmaz.</p>${v.productionOrders.map(p=>`<button class="flow-parent" onclick="RitimPremiumAPI.poOpen(${jsArg(p.id)})"><b>${h(p.number)}</b><span>${p.quantity} adet · ${p.compensation?'Telafi':'Normal üretim'} · ${h(poStatus(p.planningState))}</span></button>`).join('')||'<p>Henüz üretim emri yok.</p>'}${v.jobs.map(j=>`<div class="flow-operation"><div><b>${j.sequence+1}. ${h(j.operation)}</b><small>${h(j.reason)}</small></div><span>${j.produced} / ${j.quantity} işlem adedi</span><button class="btn sm" onclick="RitimPremiumAPI.openJob(${jsArg(j.id)},${jsArg(j.orderId)})">İşi aç</button></div>`).join('')}</details></section>${orderRecoveryPanel()}`}
 function productionMonitorContentOriginal(){const rows=monitorJobs.filter(j=>monitorFilter==='all'||monitorFilter==='running'&&j.status==='running'||monitorFilter==='ready'&&j.ready||monitorFilter==='blocked'&&j.blockers?.length);return `<section class="flow-monitor"><div class="card pad"><div class="flow-heading"><div><h2>Üretim takibi</h2><p>İç ve fason işler · Güncel çalışma ve bekleme nedenleri</p></div><button class="btn" onclick="RitimPremiumAPI.navigate('production-monitor')">Yenile</button></div><div class="flow-metrics">${flowMetric('Çalışan',monitorJobs.filter(j=>j.kind==='internal'&&j.status==='running').length)}${flowMetric('Fasondaki işler',monitorJobs.filter(j=>j.supplierOutstanding>0).length)}${flowMetric('Ön koşulları hazır',monitorJobs.filter(j=>j.ready).length)}${flowMetric('Karar / girdi bekleyen',monitorJobs.filter(j=>j.blockers?.length).length)}</div><nav class="flow-filters" aria-label="Üretim takibi filtresi">${[['all','Tümü'],['running','Çalışan'],['ready','Hazır'],['blocked','Bekleyen']].map(([id,label])=>`<button class="btn" aria-pressed="${monitorFilter===id}" onclick="RitimPremiumAPI.monitorFilter(${jsArg(id)})">${label}</button>`).join('')}</nav></div><div class="flow-job-grid">${rows.map(j=>`<article class="card pad"><span class="pill">${h(j.kind==='external'?'Fason':poStatus(j.status))}</span><h3>${h(j.partName)}</h3><p>${h(j.operation)} · ${h(j.orderNumber)}</p><p>${h(j.machineCode||'Makine atanmamış')} · ${j.produced} / ${j.quantity} işlem adedi</p><p class="flow-reason">${h(j.reason)}</p><button class="btn" onclick="${j.kind==='external'&&j.productionOrderId?`RitimPremiumAPI.openSupplierJob(${jsArg(j.productionOrderId)},${jsArg(j.id)})`:`RitimPremiumAPI.openJob(${jsArg(j.id)},${jsArg(j.orderId)})`}">İşi incele</button></article>`).join('')||'<div class="card pad">Bu filtrede açık iş bulunmuyor.</div>'}</div></section>`}

 function supplierQueueContent(){const rows=monitorJobs.filter(x=>x.kind==='external').sort((a,b)=>Number(b.supplierOutstanding>0)-Number(a.supplierOutstanding>0));return '<section class="card pad operations-workspace operations-suppliers"><div class="flow-heading"><div><span class="flow-eyebrow">FASON TAKİBİ</span><h2>Fason işleri</h2><p>Üretim emirlerindeki dış operasyonlar ve bekleyen dönüşler</p></div><button class="btn" onclick="RitimPremiumAPI.navigate(\'outsourcing\')">Yenile</button></div><div class="flow-job-grid">'+rows.map(j=>'<article class="card pad"><h3>'+h(j.partName)+'</h3><p>'+h(j.operation)+' · '+h(j.orderNumber)+'</p><p>Dışarıda '+j.supplierOutstanding+' adet · Kalite bekleyen '+j.qualityPending+' adet</p><p class="flow-reason">'+h(j.reason)+'</p><button class="btn" onclick="RitimPremiumAPI.openSupplierJob(\''+j.productionOrderId+'\',\''+j.id+'\')">Fason takibini aç</button></article>').join('')+(rows.length?'':'<p>Açık fason işi bulunmuyor.</p>')+'</div></section>'}
 function workspaceFilters(v,fresh=false){const defaults=v==='jobs'?{...(clarityRead().jobFilters||{}),...(viewPreferences.jobs?.settings||{})}:{},p=new URLSearchParams(location.search);if(fresh||p.get('view')!==v)return {...defaults};const keys=v==='overview'?['category','q']:['q','status','machineId','operatorId'];return {...defaults,...Object.fromEntries(keys.filter(k=>p.get(k)).map(k=>[k,p.get(k)]))}}
 function workspaceSearch(){const v=page==='overview'?daily:worklist,f=workspaceFilters(page);return `<form class="worklist-filters" onsubmit="event.preventDefault();RitimPremiumAPI.filterWorkspace()"><label class="formfield">Arama<input id="workspace-query" class="input" type="search" maxlength="120" value="${h(v.query)}" placeholder="Sipariş, müşteri veya parça"></label>${page==='jobs'?`<label class="formfield">Durum<select class="select" id="workspace-status">${[['active','Açık işler'],['all','Tüm durumlar'],['waiting','Başlamadı'],['running','Çalışıyor'],['paused','Duraklatıldı'],['complete','Tamamlandı'],['cancelled','İptal edildi']].map(([id,t])=>`<option value="${id}" ${v.status===id?'selected':''}>${t}</option>`).join('')}</select></label>${[['machineId','Makine',v.machines],['operatorId','Operatör',v.operators]].map(([k,t,rows])=>`<label class="formfield">${t}<select class="select" id="workspace-${k}"><option value="">Tümü</option>${rows.map(x=>`<option value="${x.id}" ${f[k]===x.id?'selected':''}>${h(x.code||x.name)}</option>`).join('')}</select></label>`).join('')}`:''}<button class="btn primary" type="submit">Filtrele</button><button class="btn" type="button" onclick="RitimPremiumAPI.navigate('${page}')">Temizle</button></form>${preferenceControls(page)}`}
 function dailyContentOriginal(){if(!daily)return '<p>Günlük işler yükleniyor…</p>';return `<section class="daily-workspace"><div class="card pad flow-heading"><div><span class="flow-eyebrow">GÜNLÜK ÇALIŞMA ALANI</span><h2>Bugün neye odaklanmalıyız?</h2><p>${h(daily.today)} · İşlem bekleyen kayıtları doğrudan açın.</p></div><button class="btn" onclick="RitimPremiumAPI.refreshWorkspace()">Yenile</button></div><div class="daily-metrics">${daily.categories.slice().sort((a,b)=>Number(daily.counts[b.id]>0)-Number(daily.counts[a.id]>0)).map(c=>`<button class="card pad daily-metric ${daily.counts[c.id]?'':'daily-metric-zero'}" aria-pressed="${daily.category===c.id}" onclick="RitimPremiumAPI.dailyCategory(${jsArg(c.id)})"><strong>${daily.counts[c.id]}</strong><span>${h(c.label)}</span></button>`).join('')}</div><section class="card pad"><h3>${h(daily.categories.find(c=>c.id===daily.category)?.label)}</h3>${workspaceSearch()}<div class="workspace-list">${daily.items.map(x=>`<article class="workspace-row"><div><h4>${h(x.label)}</h4><p>${h(x.detail)}</p>${x.dueDate?`<small>Tarih: ${h(x.dueDate)}</small>`:''}</div><button class="btn" onclick="RitimPremiumAPI.dailyOpen(${jsArg(x.id)})">İncele →</button></article>`).join('')||'<div class="workspace-empty"><h4>Bu listede bekleyen kayıt yok</h4><p>Diğer iş gruplarını inceleyebilir veya aramayı değiştirebilirsiniz.</p></div>'}</div>${daily.nextAfter?'<button class="btn" onclick="RitimPremiumAPI.moreWorkspace()">Daha fazla göster</button>':''}</section></section>`}
 function worklistContent(){return compactWorklistContent()}
 async function reloadWorkspace(filters,append=false){if(!append&&listPaging[page]){listPaging[page].page=1;delete listSorts[page]}const target=page,url=new URL(location.href);['category','q','status','machineId','operatorId','after'].forEach(k=>url.searchParams.delete(k));Object.entries(filters).forEach(([k,v])=>{if(v&&k!=='after')url.searchParams.set(k,v)});url.searchParams.set('view',target);const result=target==='overview'?await api.workCenter(filters):await api.jobWorklist(filters);if(append){const old=target==='overview'?daily:worklist;result.items=[...old.items,...result.items]}if(target==='overview')daily=result;else worklist=result;history.replaceState({ritimView:target},'',url)}
 function orderListFilters(fresh=false){const p=new URLSearchParams(location.search),defaults=viewPreferences.orders?.settings||{};if(fresh||p.get('view')!=='orders')return {...defaults};return {...defaults,...Object.fromEntries(['q','status','sort','direction','page','dueFrom','dueTo','allocation','number','customer','part','quantityFrom','quantityTo'].filter(k=>p.has(k)).map(k=>[k,p.get(k)]))}}
 function orderListContent(){const v=ordersWorkspace;if(!v)return '<section class="card pad">Siparişler yükleniyor…</section>';const f=v.filters,sortLabels={due:'Termin',created:'Kayıt tarihi',customer:'Müşteri',quantity:'Adet',number:'Sipariş numarası',priority:'Öncelik'};return `<section class="workspace-orders"><div class="card pad order-toolbar"><div class="flow-heading"><div><h2>${v.total} sipariş</h2><p>${h(sortLabels[f.sort]||'Termin')} · ${f.direction==='desc'?'azalan':'artan'}<span id="orders-filter-notice" role="status"></span></p></div><button class="btn primary" onclick="openWizard()" ${capable('orders.write')?'':'disabled'}>Yeni Sipariş</button></div><form oninput="RitimPremiumAPI.orderFilterDraft()" onchange="RitimPremiumAPI.orderFilterDraft()" onsubmit="event.preventDefault();RitimPremiumAPI.filterOrders()"><div class="order-workspace-filters"><label class="formfield">Sipariş ara<input class="input" id="orders-query" type="search" maxlength="120" value="${h(f.q)}" placeholder="Sipariş, müşteri, parça veya referans"></label><label class="formfield">Durum<select class="select" id="orders-status">${[['open','Açık siparişler'],['all','Tüm durumlar'],['closed','Kapalı'],['cancelled','İptal edildi']].map(([id,t])=>`<option value="${id}" ${f.status===id?'selected':''}>${t}</option>`).join('')}</select></label><button class="btn" type="submit">Uygula</button></div><details class="flow-details"><summary>Filtre ve sıralama</summary><div class="formgrid"><label class="formfield">Sıralama<select class="select" id="orders-sort">${[['part','Parça'],['allocated','Üretime ayrılan'],['remaining','Kalan'],['delivered','Net teslim'],['status','Durum'],['due','Termin'],['created','Kayıt tarihi'],['customer','Müşteri'],['quantity','Adet'],['number','Sipariş numarası'],['priority','Öncelik']].map(([id,t])=>`<option value="${id}" ${f.sort===id?'selected':''}>${t}</option>`).join('')}</select></label><label class="formfield">Yön<select class="select" id="orders-direction"><option value="asc" ${f.direction==='asc'?'selected':''}>Artan / önce</option><option value="desc" ${f.direction==='desc'?'selected':''}>Azalan / sonra</option></select></label><label class="formfield">Termin başlangıcı<input class="input" id="orders-dueFrom" type="date" value="${h(f.dueFrom)}"></label><label class="formfield">Termin sonu<input class="input" id="orders-dueTo" type="date" value="${h(f.dueTo)}"></label><label class="formfield">Üretime ayrılma<select class="select" id="orders-allocation">${[['all','Tümü'],['remaining','Ayrılabilir miktarı var'],['allocated','Tamamı ayrılmış']].map(([id,t])=>`<option value="${id}" ${f.allocation===id?'selected':''}>${t}</option>`).join('')}</select></label></div><button class="btn sm" type="submit">Filtreleri uygula</button><button class="btn sm" type="button" onclick="RitimPremiumAPI.resetOrders()">Temizle</button></details></form>${preferenceControls('orders')}</div>${RitimOrderGrid.render(v,{h,jsArg,date:workspaceDate,status:displayStatus,can:capable})}<div class="workspace-pagination"><button class="btn" onclick="RitimPremiumAPI.ordersPage(${v.page-1})" ${v.page<=1?'disabled':''}>← Önceki</button><span>Sayfa ${v.page} / ${v.pages} · ${v.total} sipariş</span><button class="btn" onclick="RitimPremiumAPI.ordersPage(${v.page+1})" ${v.page>=v.pages?'disabled':''}>Sonraki →</button></div><p class="tiny">Liste sıralaması üretim önceliğini veya makine kuyruklarını değiştirmez.</p></section>`}
 async function loadOrderWorkspace(filters){ordersWorkspace=await api.orderWorkspace(filters);const u=new URL(routeUrl('orders'),location.href);for(const k of ['page','dueFrom','dueTo','allocation','number','customer','part','quantityFrom','quantityTo'])u.searchParams.delete(k);for(const [k,v] of Object.entries({...ordersWorkspace.filters,page:ordersWorkspace.page}))if(v)u.searchParams.set(k,v);history.replaceState({},'',u);ordersLocation=u.href}
 function editMasterPicker(key,label){return `<label class="formfield">${label}<input class="input" id="edit-${key}-search" value="${h(key==='customer'?editDraft.customer:editDraft.partName)}" ${editModel.identityLocked?'disabled':''} autocomplete="off" role="combobox" aria-expanded="false" aria-controls="edit-${key}-results" oninput="RitimPremiumAPI.editMasterSearch('${key}',this.value)" onkeydown="if(event.key==='Escape'){document.getElementById('edit-${key}-results').innerHTML='';this.setAttribute('aria-expanded','false')}"></label><div id="edit-${key}-results" class="edit-master-results"></div>${capable('master.write')&&!editModel.identityLocked?`<button type="button" class="master-quick-add" onclick="RitimPremiumAPI.quickMaster('${key}','edit')">+ Yeni ${key==='customer'?'müşteri':'parça'} ekle</button>`:''}`}
 function orderEditContent(){if(!editModel)return '';const d=editDraft,o=editModel;return `<section class="card pad order-edit-panel"><button class="btn sm" onclick="RitimPremiumAPI.openOrder(${jsArg(o.id)})">← Siparişe dön</button><span class="flow-eyebrow">GÜVENLİ DÜZENLEME</span><h2>${h(o.orderNumber)}</h2><p>${o.identityLocked?'Üretim veya teknik çizim bağlantısı var. Müşteri ve parça korunur; miktar ve termin değişikliği gerekçeyle kaydedilir.':'Üretime ayrılmamış siparişin temel bilgilerini düzenleyebilirsiniz.'}</p>${conflictContent()}<form oninput="RitimPremiumAPI.editReview()" onsubmit="event.preventDefault();RitimPremiumAPI.saveOrderEdit()"><fieldset class="edit-fieldset" ${editConflict?'disabled':''}>${editMasterPicker('customer','Müşteri')}${o.itemized?'<p class="order-hint">Ürünler sipariş kalemlerinde tutulur: '+(o.items||[]).map(x=>h(x.partName)+' · '+x.orderedQuantity+' adet').join(' / ')+'</p>':editMasterPicker('part','Parça')}<div class="formgrid"><label class="formfield">Sipariş adedi<input class="input" id="edit-quantity" ${o.itemized?'readonly':''} type="number" min="${o.minimumQuantity||Math.max(1,o.allocated)}" step="1" required value="${d.orderedQuantity}" oninput="RitimPremiumAPI.editPreview()"></label><label class="formfield">Termin<input class="input" type="date" id="edit-due" value="${h(d.dueDate||'')}" onchange="RitimPremiumAPI.editPreview()"></label></div><details class="flow-details"><summary>Ek bilgiler</summary><div class="formgrid"><label class="formfield">Müşteri referansı<input class="input" id="edit-reference" maxlength="120" value="${h(d.reference)}"></label><label class="formfield">Öncelik<select class="select" id="edit-priority">${[['0','Standart'],['1','Öncelikli'],['2','Yüksek'],['3','Acil']].map(([id,t])=>`<option value="${id}" ${Number(id)===d.priority?'selected':''}>${t}</option>`).join('')}</select></label></div><label class="formfield">Açıklama<textarea class="input" id="edit-notes" maxlength="2000">${h(d.notes)}</textarea></label></details><div class="flow-notice" id="edit-impact">Üretime ayrılmış ${o.allocated} adet korunur. Mevcut iş emirlerinin miktarı otomatik değiştirilmez.</div><label class="formfield">Değişiklik gerekçesi ${o.identityLocked?'':'· isteğe bağlı'}<input class="input" id="edit-reason" value="${h(d.reason||'')}" maxlength="120" placeholder="Örn. müşterinin revize termin talebi"></label><div id="edit-review" class="edit-review" role="status"></div><div class="production-create-footer"><button class="btn" type="button" onclick="RitimPremiumAPI.editReload()">Güncel kaydı yükle</button><button class="btn primary" type="submit" ${editConflict||o.status!=='open'?'disabled':''}>Değişiklikleri kaydet</button></div></fieldset></form></section>`}
 async function prepareBatches(id,orderItemId=null){await loadDetail(id);await loadPoOperationChoices();const info=await api.orderEditing(id);const item=info.items?.find(x=>x.id===orderItemId)||(info.items?.length===1?info.items[0]:null),remaining=info.itemized?(item?.remaining||0):Math.max(0,info.orderedQuantity-info.allocated);batchModel={orderItemId:item?.id||null,items:info.items||[],composeStep:1,orderId:id,version:info.version,remaining,operations:(info.itemized?[]:detail.route).map(x=>({name:x.name,kind:x.kind,setupMinutes:null,cycleMinutes:null})),batches:[{quantity:remaining,number:await p1Number(),plannedDate:'',custom:false,operations:[]}],preview:false}}
 function routeEditor(ops,prefix,handler){return `<div class="production-route">${ops.map((op,i)=>`<article class="card pad route-editor-operation"><div class="production-route-row"><span class="op-number">${i+1}</span><label class="formfield">Operasyon adı${catalogOperationSelect(op,prefix,i,handler==='po'?'po-edit':handler)}</label><label class="formfield">Tür<select class="select" id="${prefix}-kind-${i}" disabled><option value="internal" ${op.kind==='internal'?'selected':''}>İç operasyon</option><option value="external" ${op.kind==='external'?'selected':''}>Fason</option></select></label><div class="production-route-actions"><button type="button" class="btn sm" aria-label="${i+1}. operasyonu yukarı taşı" onclick="RitimPremiumAPI.routeChange(${jsArg(handler)},'up',${i})" ${i?'':'disabled'}>↑</button><button type="button" class="btn sm" aria-label="${i+1}. operasyonu aşağı taşı" onclick="RitimPremiumAPI.routeChange(${jsArg(handler)},'down',${i})" ${i===ops.length-1?'disabled':''}>↓</button><button type="button" class="btn sm" aria-label="${i+1}. operasyonu kaldır" onclick="RitimPremiumAPI.routeChange(${jsArg(handler)},'remove',${i})">×</button></div></div><details><summary>Tahmini süreler · isteğe bağlı</summary><div class="formgrid"><label class="formfield">Hazırlık · dakika<input class="input" id="${prefix}-setup-${i}" type="number" min="0" max="10080" step="0.001" value="${op.setupMinutes??''}"></label><label class="formfield">Adet başı · dakika<input class="input" id="${prefix}-cycle-${i}" type="number" min="0" max="10080" step="0.001" value="${op.cycleMinutes??''}"></label></div><p class="tiny">Boş bırakılan süre bilinmiyor kabul edilir. Sıfır, süre gerekmediğini belirtir.</p></details></article>`).join('')||'<p class="order-hint">Rota henüz tanımlanmadı. Üretim emri oluşturulabilir; planlamak için rota ekleyin.</p>'}</div><button class="btn" type="button" onclick="RitimPremiumAPI.routeChange(${jsArg(handler)},'add',0)">＋ Operasyon ekle</button>`}
