 function captureOrderEdit(){if(!editDraft||!el('edit-quantity'))return;Object.assign(editDraft,{orderedQuantity:Number(el('edit-quantity').value),dueDate:el('edit-due').value||null,reference:el('edit-reference').value,notes:el('edit-notes').value,priority:Number(el('edit-priority').value),reason:el('edit-reason').value});if(!editDraft.customerId)editDraft.customer=el('edit-customer-search').value;if(!editDraft.partId)editDraft.partName=el('edit-part-search')?.value??editDraft.partName}
 const compareFields=[['customer','Müşteri',['customerId','customer']],['partName','Parça',['partId','partName']],['orderedQuantity','Sipariş adedi',['orderedQuantity']],['dueDate','Termin',['dueDate']],['reference','Müşteri referansı',['reference']],['priority','Öncelik',['priority']],['notes','Açıklama',['notes']]];
 const equalGroup=(a,b,keys)=>keys.every(k=>String(a[k]??'')===String(b[k]??''));
 function conflictRows(){const c=editConflict;return compareFields.map(([key,label,keys])=>({key,label,keys,local:!equalGroup(c.base,c.mine,keys),remote:!equalGroup(c.base,c.latest,keys),same:equalGroup(c.mine,c.latest,keys),locked:c.latest.identityLocked&&['customer','partName'].includes(key)})).filter(r=>r.local||r.remote)}
 function compareValue(record,key){const value=record[key];if(key==='priority')return ['Standart','Öncelikli','Yüksek','Acil'][value]||'Standart';return value==null||value===''?'—':value}
 function conflictContent(){if(!editConflict)return '';const c=editConflict;return `<section class="version-compare" aria-labelledby="version-title"><h3 id="version-title">Kayıt değişti · taslağınız korundu</h3><p>Sürüm ${c.base.version} → ${c.latest.version}. Çakışan alanlarda hangi değerin kullanılacağını seçin. Birleştirdikten sonra kaydetmeden önce gözden geçirin.</p>${c.latest.status!=='open'?'<p role="alert">Sipariş kapatılmış. Bu sürüm üzerinde değişiklik kaydedilemez.</p>':`<p>Güncel alt miktar sınırı: ${c.latest.minimumQuantity||1} adet.${c.latest.identityLocked?' Üretim bağlantısı nedeniyle müşteri ve parça korunur.':''}</p>`}<div class="version-table"><div class="version-heading"><b>Alan</b><b>Önceki kayıt</b><b>Sunucudaki güncel</b><b>Sizin taslağınız</b><b>Kullanılacak değer</b></div>${conflictRows().map(r=>`<div class="version-row"><b>${r.label}</b><span data-label="Önceki">${h(compareValue(c.base,r.key))}</span><span data-label="Güncel">${h(compareValue(c.latest,r.key))}</span><span data-label="Taslak">${h(compareValue(c.mine,r.key))}</span><span>${r.locked?'Üretim bağlantısı · güncel kayıt korunur':r.local&&r.remote&&!r.same?`<label>Seçiminiz<select class="select" data-conflict="${r.key}" onchange="RitimPremiumAPI.conflictChoice('${r.key}',this.value)"><option value="">Seçin</option><option value="mine" ${c.choices[r.key]==='mine'?'selected':''}>Taslağımdaki</option><option value="server" ${c.choices[r.key]==='server'?'selected':''}>Güncel kayıttaki</option></select></label>`:r.local?'Taslağınızdaki korunur':'Güncel kayıttaki korunur'}</span></div>`).join('')}</div><p class="field-error" id="version-error" role="alert"></p><div class="master-editor-actions"><button class="btn" type="button" onclick="RitimPremiumAPI.resolveOrderConflict(true)">Güncel kaydı kullan</button><button class="btn primary" type="button" onclick="RitimPremiumAPI.resolveOrderConflict(false)">Seçimleri taslağa uygula</button></div></section>`}
 function captureMasterEditor(){if(!masterEditor||!el('master-name'))return;masterEditor.draft={...masterEditor.draft,...(masterEditor.kind==='parts'?{cardType:el('master-card-type')?.value||masterEditor.draft.cardType,stockUnitId:el('master-stock-unit')?.value||null}:{}),...(masterEditor.kind==='customers'?{contact:readContactFields()}:{}),name:el('master-name').value,code:el('master-code').value,...(masterEditor.kind==='operations'?{kind:el('master-kind')?.value||masterEditor.draft.kind}:{})}}
 async function openMasterEditor(kind,item,origin,key){if(busy||!capable('master.write'))return;if(kind==='parts'&&stockCardsSupported===null){try{await loadStockUnits()}catch(e){error=e.message;draw();return}}masterEditor={kind,editing:item?{...item}:null,draft:{name:item?.name||'',code:item?.code||'',kind:item?.kind||'internal',cardType:item?.cardType||'product',materials:structuredClone(item?.materials||[]),stockUnitId:item?.stockUnitId||stockUnits.find(u=>u.code==='piece')?.id||'',contact:item?.contact||{}},origin,key,focusId:origin==='wizard'?'order-'+key:origin==='edit'?'edit-'+key+'-search':document.activeElement?.id,scroll:scrollY,error:''};if(!item&&key)masterEditor.draft.name=origin==='wizard'?wizard[key]||'':editDraft[key==='customer'?'customer':'partName']||'';mountMasterEditor()}
 function closeMasterEditor(){if(busy)return;const editor=masterEditor;masterEditor=null;el('master-drawer')?.remove();if(editor?.origin==='wizard')renderModal();if(editor?.focusId)el(editor.focusId)?.focus({preventScroll:true});if(editor)scrollTo(0,editor.scroll)}
 function mountMasterEditor(){if(!masterEditor){el('master-drawer')?.remove();return}const e=masterEditor,customer=e.kind==='customers';let dialog=el('master-drawer');if(!dialog){dialog=document.createElement('dialog');dialog.id='master-drawer';dialog.className='master-drawer';dialog.setAttribute('aria-labelledby','master-drawer-title');document.body.append(dialog);dialog.addEventListener('cancel',event=>{event.preventDefault();closeMasterEditor()})}dialog.innerHTML=`<form onsubmit="event.preventDefault();RitimPremiumAPI.saveMaster()"><header><div><span class="flow-eyebrow">ANA VERİLER · ${customer?'MÜŞTERİ':e.kind==='scrap-reasons'?'HURDA NEDENİ':'STOK KARTI'}</span><h2 id="master-drawer-title">${e.editing?'Kaydı düzenle':customer?'Yeni müşteri':e.kind==='scrap-reasons'?'Yeni hurda nedeni':'Yeni stok kartı'}</h2></div><button class="btn" type="button" aria-label="Paneli kapat" onclick="RitimPremiumAPI.cancelMasterEdit()" ${busy?'disabled':''}>×</button></header><p>${e.origin==='master'?'Kaydettikten sonra aynı listeye dönersiniz.':'Kaydettikten sonra sipariş taslağınıza seçili olarak eklenir.'}</p><label class="formfield">${customer?'Müşteri / Firma adı':e.kind==='scrap-reasons'?'Hurda nedeni':'Stok kartı adı'}<input class="input" id="master-name" required maxlength="120" value="${h(e.draft.name)}" ${e.error&&e.errorField==='name'?'aria-invalid="true" aria-describedby="master-panel-error"':''}></label><label class="formfield">${customer?'Müşteri kodu':e.kind==='scrap-reasons'?'Neden kodu':'Stok kodu'} ${e.kind==='parts'&&stockCardsSupported!==false?'*':'<small>İsteğe bağlı</small>'}<input class="input" id="master-code" maxlength="120" value="${h(e.draft.code)}" ${e.error&&e.errorField==='code'?'aria-invalid="true" aria-describedby="master-panel-error"':''}></label><p class="field-error" id="master-panel-error" role="alert">${h(e.error)}</p>${e.latest?`<section class="master-version"><b>Güncel kayıt · sürüm ${e.latest.version}</b><p>${h(e.latest.name)} · ${h(e.latest.code||'Kod yok')}</p><p>Taslağınız: ${h(e.draft.name)} · ${h(e.draft.code||'Kod yok')}</p><button type="button" class="btn" onclick="RitimPremiumAPI.masterRebase(false)">Güncel kaydı kullan</button><button type="button" class="btn" onclick="RitimPremiumAPI.masterRebase(true)">Taslağımı koruyarak devam et</button></section>`:''}${journal?.list().filter(x=>x.kind==='masterData').map(x=>`<div class="master-version"><p>İşlemin sonucu henüz doğrulanmadı. Aynı işlem kimliğiyle kontrol edin.</p><button class="btn" type="button" onclick="RitimPremiumAPI.retryMaster('${x.id}')">Sonucu doğrula ve devam et</button></div>`).join('')||''}<footer><button type="button" class="btn" onclick="RitimPremiumAPI.cancelMasterEdit()" ${busy?'disabled':''}>Vazgeç</button><button class="btn primary" type="submit" ${busy||e.latest?'disabled':''}>${busy?'Kaydediliyor…':e.editing?'Değişiklikleri kaydet':'Kaydet ve devam et'}</button></footer></form>`;if(e.kind==='operations'){dialog.querySelector('#master-drawer-title').textContent=e.editing?'Operasyonu düzenle':'Yeni operasyon';const label=dialog.querySelector('#master-name').closest('label');label.firstChild.textContent='Operasyon adı';dialog.querySelector('#master-code').closest('label').firstChild.textContent='Operasyon kodu ';const field=document.createElement('label');field.className='formfield';field.innerHTML='<span>Tür *</span><select class="select" id="master-kind" required><option value="internal">İç operasyon</option><option value="external">Fason</option></select>';dialog.querySelector('#master-panel-error').before(field);field.querySelector('select').value=e.draft.kind||'internal';field.onchange=captureMasterEditor;}if(e.kind==='parts'&&stockCardsSupported!==false&&window.RitimMaterialStockUI){dialog.querySelector('#master-panel-error').insertAdjacentHTML('beforebegin',RitimMaterialStockUI.unitFields(stockUnits));dialog.querySelector('#master-card-type').value=e.draft.cardType||'product';dialog.querySelector('#master-stock-unit').value=e.draft.stockUnitId||'';dialog.querySelector('#master-panel-error').insertAdjacentHTML('beforebegin','<details class="product-materials" open><summary>Ürüne bağlı malzemeler (isteğe bağlı)</summary>'+orderMaterialsEditor(-1)+'</details>');for(const select of dialog.querySelectorAll('#master-card-type,#master-stock-unit'))select.onchange=captureMasterEditor}if(e.kind==='parts'&&stockCardsSupported===false&&!e.editing){dialog.querySelector('#master-panel-error').insertAdjacentHTML('beforebegin','<label class="formfield">Stok birimi<select class="select" disabled><option>Adet</option></select><small>Varsayılan birim Adet. Sunucu güncellemesi tamamlanmadan yeni stok kartı kaydedilemez.</small></label>');dialog.querySelector('button[type="submit"]').disabled=true}if(customer)dialog.querySelector('#master-panel-error').insertAdjacentHTML('beforebegin',contactFields(e.draft.contact));for(const input of dialog.querySelectorAll('input,textarea'))input.addEventListener('input',captureMasterEditor);if(!dialog.open)dialog.showModal();if(e.error)el('master-'+e.errorField)?.focus();else el('master-name')?.focus()}
 function completeMasterEditor(result){const e=masterEditor;if(!e||!result?.id)throw Error('Kaydedilen ana kayıt doğrulanamadı.');if(e.origin==='materials'){for(const existing of wizard.items||[])if(existing.partId===result.id)existing.materials=structuredClone(result.materials||[]);if(wizard.partId===result.id)wizard.materials=structuredClone(result.materials||[]);const line=e.key<0?wizard:wizard.items[e.key];line.materials=structuredClone(result.materials||[]);if(e.key<0){wizard.part=result.name;wizard.partNo=result.code||''}else{line.partName=result.name;line.partNumber=result.code||''}}else if(e.origin==='wizard'){wizard[e.key]=result.name;wizard[e.key+'Id']=result.id;if(e.key==='part'){wizard.partNo=result.code||'';wizard.materials=structuredClone(result.materials||[])}}else if(e.origin==='edit'){editDraft[e.key+'Id']=result.id;editDraft[e.key==='customer'?'customer':'partName']=result.name}else{const index=masterView.items.findIndex(x=>x.id===result.id);if(index>=0)masterView.items[index]=result;else if((result.name+' '+(result.code||'')).toLocaleLowerCase('tr-TR').includes(masterView.q.toLocaleLowerCase('tr-TR')))masterView.items.unshift(result);masterView.notice=e.editing?'Değişiklikler kaydedildi.':'Yeni kayıt eklendi.'}masterView.editing=null;masterEditor=null;el('master-drawer')?.remove();if(e.origin==='materials'||e.origin==='wizard')renderModal();setTimeout(()=>{if(e.focusId)el(e.focusId)?.focus({preventScroll:true});scrollTo(0,e.scroll)},0)}

