 function inventorySearchContent(kind){const v=inventoryPages[kind],materials=kind==='materials';return `<form ${materials?'data-inventory-panel="receipt stock" '+(['receipt','stock'].includes(inventoryTask)?'':'hidden'):''} class="inventory-discovery context-search" onsubmit="event.preventDefault();RitimPremiumAPI.inventorySearch('${kind}',false)"><label class="formfield">${materials?'Malzeme bul':'Hareket ara'}<input class="input" id="inventory-${kind}-query" type="search" maxlength="120" value="${h(v.q)}" placeholder="${materials?'Kod veya açıklama':'Malzeme, lot veya belge'}"></label>${materials?'':`<label class="formfield">Hareket türü<select class="select" id="inventory-movements-kind">${[['','Tüm hareketler'],['receipt','Mal kabul'],['move','Taşıma'],['pick','Üretime malzeme teslimi'],['scrap','Depo hurdası'],['raw_return','Üretimden iade'],['supplier_return','Tedarikçiye iade'],['correction','Düzeltme']].map(([key,label])=>`<option value="${key}" ${key===v.kind?'selected':''}>${label}</option>`).join('')}</select></label>`}<button class="btn" type="submit">Ara</button><button class="btn" type="button" onclick="RitimPremiumAPI.inventorySearch('${kind}',false,true)">Temizle</button>${v.nextAfter?`<button class="btn" type="button" onclick="RitimPremiumAPI.inventorySearch('${kind}',true)">Daha fazla göster</button>`:''}<small role="status">${inventoryView[kind].length} / ${v.total} kayıt</small></form>`}

