   lane.innerHTML=`<header><strong>${h(l.name)}</strong><small>Fason · ${l.jobs.length} kayıt</small></header><div class="supplier-planning-jobs">${l.jobs.map(j=>`<button type="button" class="planning-job supplier-planning-job" onclick="RitimPremiumAPI.openSupplierJob(${jsArg(j.productionOrderId)},${jsArg(j.id)})"><small>${h(j.state==='outside'?'Tedarikçide':j.state==='returned'?'Geri döndü · Kontrol / kapanış':'Gönderim bekliyor')}</small><strong>${h(j.partName)}</strong><span>${h(j.operation)}</span><small>${h(j.orderNumber)}</small><footer><b>${j.quantity} adet</b><span>${j.expectedReturnDate?'Dönüş: '+h(workspaceDate(j.expectedReturnDate)):j.state==='outside'?'Dönüş tarihi yok':''}</span></footer></button>`).join('')}</div>`;
   target.append(lane);
