 function stockFiltersContent(){const x=inventoryView,materials=[...new Map(x.balances.map(b=>[b.materialId,{id:b.materialId,code:b.materialCode}])).values()],locations=[...new Set(x.balances.map(b=>b.locationId))];return `<div class="stock-filter-row"><label class="formfield" data-inventory-panel="stock" ${inventoryTask==='stock'?'':'hidden'}>Malzeme<select class="select" id="stock-material-filter" onchange="RitimPremiumAPI.stockFilter('material',this.value)"><option value="">Tüm malzemeler</option>${materials.map(m=>`<option value="${h(m.id)}" ${inventoryStockMaterial===m.id?'selected':''}>${h(m.code)}</option>`).join('')}</select></label><label class="formfield" data-inventory-panel="stock" ${inventoryTask==='stock'?'':'hidden'}>Konum<select class="select" id="stock-location-filter" onchange="RitimPremiumAPI.stockFilter('location',this.value)"><option value="">Tüm konumlar</option>${locations.map(id=>`<option value="${h(id)}" ${inventoryStockLocation===id?'selected':''}>${h(x.locations.find(l=>l.id===id)?.code||shortReference(id))}</option>`).join('')}</select></label><label class="formfield">Lot veya konum ara<input class="input" type="search" id="inventory-balance-query" value="${h(inventoryBalanceQuery)}" oninput="RitimPremiumAPI.inventoryFilterBalance(this.value)" placeholder="Lot kodu, malzeme veya konum"></label><span id="stock-visible-count" role="status"></span></div>`}
