 function operationsQualityQueue(){const limit=operationsLimits.quality,rows=qualityQueue.slice(0,limit);return `<section class="card pad operations-workspace"><header class="flow-heading"><div><span class="flow-eyebrow">KALİTE KUYRUĞU</span><h2>Kalite</h2><p>${qualityTotal} işte karar bekleniyor · ${jobs.length} iş yüklendi</p></div><button class="btn" onclick="RitimPremiumAPI.navigate('quality-list')">Kontrolleri yenile</button></header><h3>Karar bekleyen çıktılar</h3><div class="operations-queue">${rows.map(x=>`<article class="operations-row"><div><button class="operations-title" onclick="RitimPremiumAPI.openQualityJob(${jsArg(x.job.id)},${jsArg(x.job.orderId)})">${h(x.job.partName||x.job.workOrderNumber)} · ${h(x.job.operation||'')}</button><p><button class="guided-order-link" onclick="RitimPremiumAPI.orderPeek(${jsArg(x.job.orderId)})">${h(x.job.orderNumber||'Sipariş akışı')}</button> · ${h(x.job.workOrderNumber||'')}</p><small title="${h(x.output.outputLotId||x.output.eventId)}">Çıktı ${h(shortReference(x.output.outputLotId||x.output.eventId))}${x.output.provenanceStatus==='historical_unreconciled'?' · Tarihsel iz doğrulanamadı':''}</small></div><div class="operations-count"><b>${h(x.output.unresolved)}</b><small>karar bekleyen adet</small></div><button class="btn primary" onclick="RitimPremiumAPI.openQualityJob(${jsArg(x.job.id)},${jsArg(x.job.orderId)})">Kontrolü aç</button></article>`).join('')||operationsEmpty('Doğrulanabilen işlerde karar bekleyen çıktı bulunamadı.','Yeni üretim çıktıları kontrol beklediğinde burada görünür.')}</div>${qualityQueue.length>limit?`<button class="btn" onclick="RitimPremiumAPI.operationsMore('quality')">${qualityQueue.length-limit} çıktı daha göster</button>`:''}${qualityCursor?'<button class="btn" onclick="RitimPremiumAPI.moreQuality()">Daha fazla bekleyen iş</button>':''}${qualityQueueErrors.length?`<div class="operations-warning" role="alert"><p>Bazı iş emirlerinin kalite durumu alınamadı; bekleyenler listesi eksik olabilir.</p>${qualityQueueErrors.map(x=>`<p>${h(x.job.workOrderNumber)} · ${h(x.message)} <button class="btn" onclick="RitimPremiumAPI.openQualityJob(${jsArg(x.job.id)},${jsArg(x.job.orderId)})">İşi aç</button></p>`).join('')}</div>`:''}</section>`}
 function operationsReworkRows(){return reworkDecisions.filter(d=>reworkHistory||d.available>0||d.allocations.some(a=>a.outstanding>0&&!['complete','cancelled'].includes(a.status)))}
 function operationsRework(markup){const t=operationsTemplate(markup),root=t.content.firstElementChild;root.classList.add('operations-workspace','operations-rework');const rows=[...root.children].filter(e=>e.tagName==='ARTICLE');for(const [i,row]of rows.entries()){row.classList.add('operations-rework-row');if(i>=operationsLimits.rework)row.remove();const p=row.querySelector('p');if(p){p.title=p.textContent;p.textContent=p.textContent.replace(/Çıktı lotu .+$/, 'Çıktı lotu '+shortReference(row.querySelector('[onclick*="openLotTrace"]')?.getAttribute('onclick')?.match(/\('([^']+)/)?.[1]||'İz bilgisi'));}const fields=[...row.querySelectorAll(':scope > .formfield, :scope > .btn.primary')];if(fields.length){const form=document.createElement('div');form.className='operations-inline';fields[0].before(form);fields.forEach(e=>form.append(e));}}
 if(operationsReworkRows().length>operationsLimits.rework)root.insertAdjacentHTML('beforeend',`<button class="btn" onclick="RitimPremiumAPI.operationsMore('rework')">${operationsReworkRows().length-operationsLimits.rework} tamir kaydı daha göster</button>`);return t.innerHTML}
 function qualityScreen(){const t=operationsTemplate(qualityScreenOriginal()),root=t.content.firstElementChild;if(!root)return t.innerHTML;root.classList.add('operations-workspace','operations-quality');const heading=root.querySelector('h2'),job=jobs.find(j=>j.id===jobSelected);heading.textContent=detail?.partName||job?.workOrderNumber||'Kalite kontrol';heading.insertAdjacentHTML('afterend',`<p class="operations-context">Kalite kontrol · ${h(job?.workOrderNumber||'İş emri')} · <b>${qualityView.outputs.reduce((n,o)=>n+Number(o.unresolved||0),0)} adet karar bekliyor</b></p>`);for(const row of root.querySelectorAll(':scope > article')){row.classList.add('operations-quality-output');const p=row.querySelector('p');if(p){const full=p.textContent;p.title=full;p.textContent='Üretim çıktısı · '+shortReference(qualityView.outputs.find(o=>full.includes(o.eventId))?.outputLotId||'Lot bilgisi');}}return t.innerHTML}
 function operationsOrderContext(t,id){const select=t.content.querySelector('#'+id);if(!select)return;const search=select.closest('section').querySelector('form:has(#context-order-query)'),label=select.closest('label'),box=document.createElement('details');box.className='operations-order-context';box.open=!selected;const option=select.selectedOptions[0];box.innerHTML=`<summary><span>Seçili sipariş</span><strong>${h(option?.textContent||'Sipariş seçin')}</strong><small>Değiştir / ara</small></summary>`;label.before(box);if(search)box.append(search);box.append(label)}
 function operationsShippingQuantity(){if(shippingTask==='allocate')return shippingView.totals?.availableToShip;const list=logisticsRecord?.kind==='shipping'?shippingView.shippingOrders.filter(x=>x.id===logisticsRecord.id):shippingView.shippingOrders,active=list.find(x=>x.id===shippingSelectedId)||list[0],events=shippingView.events.filter(x=>x.shippingOrderId===active?.id),source=shippingTask==='dispatch'?'allocate':'dispatch',target=shippingTask==='dispatch'?'dispatch':'deliver',key=shippingTask==='dispatch'?'allocationId':'dispatchId';return events.filter(x=>x.type===source).reduce((n,x)=>n+Math.max(0,x.quantity-events.filter(e=>e.type===target&&e[key]===x.id).reduce((sum,e)=>sum+e.quantity,0)),0)}
 function shippingSources(){const describe=l=>[l?.partName,l?.partNumber,l?.lotCode||l?.productionNumber].filter(Boolean).join(' · ');const v=shippingView,activeId=logisticsRecord?.kind==='shipping'?logisticsRecord.id:shippingSelectedId,active=v.shippingOrders.find(x=>x.id===activeId)||v.shippingOrders[0],events=v.events.filter(e=>e.shippingOrderId===active?.id),items=[];for(const type of ['dispatch','allocate']){if(shippingTask==='allocate'||(shippingTask==='dispatch'&&type==='dispatch'))continue;for(const e of events.filter(e=>e.type===type)){const next=type==='allocate'?'dispatch':'deliver',key=type==='allocate'?'allocationId':'dispatchId',available=e.quantity-events.filter(x=>x.type===next&&x[key]===e.id).reduce((n,x)=>n+x.quantity,0);if(available>0)items.push({key:type+':'+e.id,command:next,payload:{[key]:e.id},available,label:[describe(v.lots.find(l=>l.lotId===e.outputLotId)),type==='dispatch'?'Yolda':'Ayrılmış',available+' adet'].filter(Boolean).join(' · ')})}}for(const l of v.lots.filter(l=>l.availableToShip>0))items.push({key:'lot:'+l.lotId,command:'allocate',payload:{outputLotId:l.lotId},available:l.availableToShip,label:(describe(l)||'Onaylı lot')+' · '+l.availableToShip+' adet'});for(const l of (v.returnedLots||[]).filter(l=>Math.min(l.availableToShip,v.totals.availableToShip)>0))items.push({key:'return:'+l.releaseId,command:'allocate',payload:{outputLotId:l.lotId,rmaReleaseId:l.releaseId},available:Math.min(l.availableToShip,v.totals.availableToShip),label:'İade ürünü · '+l.availableToShip+' adet'});return items}
 function shippingContent(){const t=operationsTemplate(shippingContentOriginal());operationsOrderContext(t,'ship-order');const root=t.content.firstElementChild;root.classList.add('operations-workspace','shipping-compact');if(!(shippingView.totals?.availableToShip>0)){const create=root.querySelector('button[onclick*="shippingAction"]');if(create){create.disabled=true;create.title='Sevkiyat için uygun ürün yok'}}const panel=root.querySelector('.flow-shipping-step'),labels={allocate:'Sevkiyat için ayır',dispatch:'Çıkış yap',deliver:'Teslim et'};if(panel){const sources=shippingSources(),first=sources[0];panel.innerHTML=`<label class="formfield">Lot<select id="ship-source" class="select">${sources.map(x=>`<option value="${h(x.key)}">${h(x.label)}</option>`).join('')}</select></label><label class="formfield">Adet<input id="ship-quantity" class="input" type="number" inputmode="numeric" min="1" step="1" max="${first?.available||0}" value="${first?.available||''}"></label><p class="shipping-action-hint">${shippingTask==='allocate'?'Ürün depoda kalır.':shippingTask==='dispatch'?'Ürün depodan çıkar.':'Müşteriye teslim edildi olarak kaydedilir.'}</p><button class="btn primary" onclick="RitimPremiumAPI.shippingAction('${shippingTask}')" ${first?'':'disabled'}>${labels[shippingTask]}</button>${first?'':'<p>Uygun ürün yok.</p>'}`;root.querySelectorAll('.shipping-operation nav button').forEach((b,i)=>b.textContent=Object.values(labels)[i]);const totals=shippingView.totals||{};root.querySelector('.shipping-operation nav').insertAdjacentHTML('beforebegin',`<div class="shipping-brief"><span>Uygun: <b>${totals.availableToShip||0}</b></span><span>Ayrılan: <b>${totals.awaitingDispatch||0}</b></span><span>Yolda: <b>${totals.inTransit||0}</b></span><span>Teslim: <b>${totals.delivered||0}</b></span></div>`)}return t.innerHTML}
