 function mountCompletionCues(){if(page!=='detail'||!orderSummary||orderSummary.orderId!==detail?.id)return;const root=document.querySelector('.flow-order-summary');if(!root)return;if(root.classList.contains('guidance-order-summary'))return;const v=orderSummary,closed=v.status==='closed',quantity=v.orderedQuantity,productionDone=v.jobs.length>0&&v.jobs.every(j=>j.status==='complete'),dispatched=v.shipping.dispatched>=quantity,delivered=v.shipping.netDelivered>=quantity,icons=['order','allocation','repair','package','truck','check'];for(const [i,card]of [...root.querySelectorAll(':scope > .flow-metrics > .flow-metric')].entries()){card.classList.add('outcome-metric');card.insertAdjacentHTML('afterbegin','<span class="outcome-metric-icon">'+outcomeIcon(icons[i])+'</span>');if((i===4&&dispatched)||(i===5&&delivered)){card.classList.add('is-fulfilled');card.insertAdjacentHTML('beforeend','<span class="outcome-card-check" aria-label="Hedef miktara ulaşıldı">'+outcomeIcon('check')+'</span>')}}if(closed){root.classList.add('is-closed-order');const banner=document.createElement('div');banner.className='order-outcome-banner';banner.setAttribute('role','status');banner.innerHTML='<span class="order-outcome-seal">'+outcomeIcon('check')+'</span><div><strong>Sipariş kapatıldı</strong><p>'+v.shipping.netDelivered+' / '+quantity+' adet net teslim</p></div><div class="order-outcome-stages">'+[['production','Üretim',productionDone],['truck','Sevkiyat',dispatched],['package','Teslimat',delivered]].map(([icon,label,done])=>'<span class="'+(done?'is-done':'')+'">'+outcomeIcon(done?'check':icon)+'<b>'+label+'</b></span>').join('')+'</div>';root.querySelector('.flow-metrics')?.before(banner)}}

