 async saveOrderEdit(){if(busy||editConflict||editModel?.status!=='open')return;captureOrderEdit();const o=editModel,p={version:o.version,customerId:editDraft.customerId,partId:editDraft.partId,orderedQuantity:editDraft.orderedQuantity,dueDate:editDraft.dueDate,reference:editDraft.reference,notes:editDraft.notes,priority:editDraft.priority,reason:editDraft.reason};if(!o.identityLocked&&(!p.customerId||!o.itemized&&!p.partId))return toast('Müşteri ve parçayı kayıtlı sonuçlardan seçin.');const origin=scope;await run(async()=>{try{await experienceCommand('orderUpdate',o.id,'',p)}catch(e){if(!['VERSION_CONFLICT','IDENTITY_LOCKED','QUANTITY_ALLOCATED','ORDER_CLOSED'].includes(e.code))throw e;const latest=await api.orderEditing(o.id);if(scope===origin&&editModel?.id===o.id)editConflict={base:{...o},mine:{...editDraft},latest,choices:{}};return}await loadDetail(o.id);orderRecovery=await api.compensationOptions(o.id);orderClosing=await api.orderClosing(o.id);editModel=null;editConflict=null;page='detail';history.pushState({},'',routeUrl(page,o.id))})},
