 async batchAdd(){if(busy)return;captureBatches();if(batchModel.batches.length>=50)return toast('En fazla 50 parti oluşturabilirsiniz.');const used=batchModel.batches.reduce((n,b)=>n+b.quantity,0);await run(async()=>{const number=await p1Number();batchModel.batches.push({quantity:Math.max(1,batchModel.remaining-used),plannedDate:'',number,custom:false,operations:[]});batchModel.preview=false})},
