 batchPreview(plan){if(plan)for(const field of document.querySelectorAll('input[id^="batch-date-"]'))if(!field.value)field.value=dispatchToday();captureBatches();const d=batchModel,total=d.batches.reduce((n,b)=>n+b.quantity,0);if(!Number.isSafeInteger(total)||total>d.remaining||d.batches.some(b=>!Number.isSafeInteger(b.quantity)||b.quantity<1))return toast('Partilerin toplamı kalan miktarı aşmamalı; her parti pozitif adet olmalı.');const rows=d.batches.map(b=>({quantity:b.quantity,number:b.number,plannedDate:b.plannedDate||null,plan:plan&&!!b.plannedDate,operations:structuredClone(b.custom?b.operations:d.operations)}));if(rows.some(b=>b.operations.some(op=>!op.name.trim())))return toast('Operasyon adlarını tamamlayın.');if(rows.some(b=>b.plan&&!b.operations.length))return toast('Planlanacak partilerin operasyon rotasını ekleyin.');if(plan&&!rows.some(b=>b.plan))return toast('Planlanacak en az bir partiye tarih girin.');d.preview={rows,planCount:rows.filter(b=>b.plan).length,jobCount:rows.filter(b=>b.plan).reduce((n,b)=>n+b.operations.length,0)};draw();document.querySelector('.batch-preview')?.scrollIntoView({block:'center',behavior:'smooth'})},
