 async newCompensation(){if(busy||!capable('orders.write'))return;const d=workflowDialog('Yeni telafi',`<p>Telafi için sipariş seçin. Belgelenmiş kayıplar sonraki adımda gösterilir.</p><form id="compensation-order-search"><label class="formfield">Sipariş ara<input class="input" type="search" id="compensation-order-query" placeholder="Sipariş, müşteri veya parça"></label><button class="btn" type="submit">Ara</button></form><div id="compensation-order-results" role="status"></div>`);let revision=0;const search=async()=>{const version=++revision,target=d.querySelector('#compensation-order-results');target.textContent='Yükleniyor…';try{const result=await api.orderChoices({q:d.querySelector('input').value.trim(),limit:30});if(version!==revision||!d.isConnected)return;target.replaceChildren();for(const item of result.items){const b=document.createElement('button');b.className='btn';b.textContent=[item.orderNumber,item.customer,item.partName].filter(Boolean).join(' · ');b.onclick=()=>{d.close();d.remove();this.openRecovery(item.id)};target.append(b)}if(!result.items.length)target.textContent='Eşleşen sipariş yok.'}catch(e){if(version===revision)target.textContent=e.message}};d.querySelector('form').onsubmit=e=>{e.preventDefault();void search()};await search()},
