 async orderNext(){const n=orderSummary?.guidance?.next||orderSummary?.next;if(!n)return;if(!nextActionAllowed(n.target))return this.navigate('production-monitor');if(n.target==='supplier')return n.productionOrderId?this.openSupplierJob(n.productionOrderId,n.jobId):this.openJob(n.jobId,detail.id);if(n.target==='job')return this.openJob(n.jobId,detail.id);if(n.target==='quality-list'&&n.jobId&&capable('quality.write'))return this.openQualityJob(n.jobId,detail.id);if(n.target==='production-create')return this.openBatches(detail.id);if(n.target==='production-orders')return this.poListOrder(detail.id);if(['history','closing'].includes(n.target)){const panel=el('order-recovery-panel');if(panel){panel.open=true;panel.scrollIntoView({block:'start',behavior:'smooth'})}return}if(!allowedPage(n.target))return this.navigate('production-monitor');const id=detail.id;await this.navigate(n.target);if(n.target==='shipping')await run(async()=>{selected=id;shippingView=await api.shippingRead(id);shippingTask=n.task||'allocate';clarityShippingOpen=true;history.replaceState({},'',routeUrl('shipping',id))})},

