 openWorkOrderComposer(){const p=poDetail,date=el('po-plan-date')?.value||dispatchToday(),dialog=workflowDialog('İş emirlerini oluştur',`<ol class="order-steps"><li aria-current="step"><span>1</span><b>Ürün ve operasyonlar</b></li><li><span>2</span><b>Son kontrol</b></li></ol><section id="work-compose-input"><h3>${h(p.partName)}</h3><p>${h(p.number)} · ${p.quantity} adet</p><ol>${p.route.map(op=>`<li>${h(op.name)} · ${op.kind==='external'?'Fason':'İç operasyon'}</li>`).join('')}</ol><label class="formfield">Hedef tarih<input class="input" type="date" id="work-compose-date" value="${h(date)}" required></label><button class="btn primary" type="button" id="work-compose-next">Devam et →</button></section><section id="work-compose-review" hidden><h3>Kaydetmeden önce</h3><p>${h(p.partName)} için ${p.quantity} adetlik ${p.route.length} iş emri oluşturulacak.</p><p>İş emirleri bu üretim emrinin ürün kalemine bağlıdır. Makine ve operatör ataması Planlama ekranından yapılır.</p><p id="work-compose-summary"></p><button class="btn" type="button" id="work-compose-back">← Geri</button><button class="btn primary" type="button" id="work-compose-save">Onayla ve oluştur</button></section>`);const steps=dialog.querySelectorAll('.order-steps li');dialog.querySelector('#work-compose-next').onclick=()=>{const field=dialog.querySelector('#work-compose-date');if(!field.reportValidity())return;dialog.querySelector('#work-compose-summary').textContent='Hedef tarih: '+workspaceDate(field.value);dialog.querySelector('#work-compose-input').hidden=true;dialog.querySelector('#work-compose-review').hidden=false;steps[0].removeAttribute('aria-current');steps[1].setAttribute('aria-current','step')};dialog.querySelector('#work-compose-back').onclick=()=>{dialog.querySelector('#work-compose-input').hidden=false;dialog.querySelector('#work-compose-review').hidden=true;steps[1].removeAttribute('aria-current');steps[0].setAttribute('aria-current','step')};dialog.querySelector('#work-compose-save').onclick=()=>{const field=el('po-plan-date');if(!field)return;field.value=dialog.querySelector('#work-compose-date').value;dialog.close();dialog.remove();this.poState('plan',true)}},
 async poResumeJob(id){if(busy||!poDetail||!capable('production.write'))return;const p=poDetail,j=p.workOrders.find(x=>x.id===id&&x.kind==='internal'&&x.status==='paused');if(!j||p.planningState!=='planned'||j.attention?.executionHeld||detail?.executionHold)return;await run(async()=>{if(journal.list().some(x=>x.kind==='production'&&x.body.workOrderId===id))throw Error('Önce bu işin sonucu belirsiz işlemini doğrulayın.');const row=await journal.begin({...scope,kind:'production',target:id,body:{orderId:p.orderId,workOrderId:id,action:'resume',payload:{}}});await journal.execute(row,r=>api.productionCommand(r.body.orderId,r.body.workOrderId,r.body.action,r.body.payload,r.id));clarityNotice='İşe devam ediliyor.';poDetail=await api.productionOrder(p.id);poFlow=await api.productionOrderFlow(p.id)})},
