 rawMaterialSuggestions(){const selected=el('raw-production'),stock=el('raw-stock');if(!selected||!stock)return;const expected=rawProductionOrders.find(p=>p.id===selected.value)?.expectedMaterials||[],ids=new Set(expected.map(m=>m.materialId)),current=stock.value;const lots=inventoryView.balances.filter(b=>b.quantity>0&&(b.partId||inventoryView.materials.some(m=>m.id===b.materialId&&m.partId)));lots.sort((a,b)=>Number(ids.has(b.materialId))-Number(ids.has(a.materialId)));stock.innerHTML='<option value="">Seçin</option>'+lots.map(b=>'<option value="'+h(b.lotId+'|'+b.locationId)+'">'+(ids.has(b.materialId)?'★ Beklenen · ':'')+h(b.materialCode)+' · '+h(b.lotCode)+' · '+h(inventoryLocationPath(b.locationId))+' · '+b.quantity+' '+h(b.unit||'piece')+'</option>').join('');stock.value=current;let note=el('raw-expected-materials');if(!note){note=document.createElement('div');note.id='raw-expected-materials';stock.closest('label').before(note)}note.innerHTML=expected.length?'<small>Sipariş ürün kaleminde beklenen toplam malzemeler</small>'+orderMaterialsSummary(expected):''},
