 async uploadQualityDecisionDocument(input){const file=input.files?.[0];if(!file||qualityDocumentUploading)return;const orderId=detail.id,jobId=jobSelected,session=qualityDialogSession,feedback=el('quality-document-feedback'),dialog=el('api-quality-dialog'),save=dialog.querySelector('.quality-dialog-actions .primary');if(qualityDecisionDocuments.length>=5){feedback.textContent='En fazla 5 belge seçebilirsiniz.';return}if(!file.size||file.size>5242880||!['application/pdf','image/jpeg','image/png'].includes(file.type)){feedback.textContent='En fazla 5 MB PDF, JPEG veya PNG seçin.';input.value='';return}qualityDocumentUploading=true;input.disabled=save.disabled=true;feedback.textContent=file.name+' yükleniyor…';try{const contentBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});const uploaded=await api.addWorkDocument(orderId,jobId,{context:'quality',filename:file.name,contentBase64},input.dataset.uploadKey||(input.dataset.uploadKey=crypto.randomUUID()));if(session!==qualityDialogSession||detail?.id!==orderId||jobSelected!==jobId||!dialog.open)return;qualityDecisionDocuments.push(uploaded.id);delete input.dataset.uploadKey;input.value='';feedback.textContent=file.name+' eklendi ve seçildi.';await loadQualityDecisionDocuments();await refreshDocumentPanel(orderId,jobId)}catch(e){if(session!==qualityDialogSession||!dialog.open)return;feedback.textContent='Belge yüklenmedi: '+e.message;input.value='';delete input.dataset.uploadKey}finally{qualityDocumentUploading=false;input.disabled=save.disabled=false}},
 async documentUpload(input,context,order,job){const file=input.files?.[0];if(!file||input.disabled)return;const section=input.closest('[data-upload-context]'),feedback=section?.querySelector('.upload-feedback'),fields=[...(section?.querySelectorAll('input')||[input])];if(!file.size||file.size>5242880||!['application/pdf','image/jpeg','image/png'].includes(file.type)){if(feedback)feedback.textContent='En fazla 5 MB PDF, JPEG veya PNG seçin.';input.value='';return}if(input._uploadFile!==file){input._uploadFile=file;delete input.dataset.commandKey}const origin=scope;fields.forEach(f=>f.disabled=true);if(feedback)feedback.textContent=file.name+' · '+Math.ceil(file.size/1024)+' KB · Yükleniyor…';try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});if(scope!==origin)return;await api.addWorkDocument(order,job,{context,filename:file.name,contentBase64:base64},input.dataset.commandKey||(input.dataset.commandKey=crypto.randomUUID()));delete input.dataset.commandKey;input.value='';await refreshDocumentPanel(order,job);if(feedback){feedback.textContent='✓ '+file.name+' eklendi.';if(file.type.startsWith('image/')){const img=document.createElement('img');img.alt=file.name;img.src='data:'+file.type+';base64,'+base64;feedback.prepend(img)}}toast('Belge eklendi.')}catch(e){if(feedback){feedback.textContent='Yüklenemedi: '+e.message+' ';const retry=document.createElement('button');retry.className='btn';retry.textContent='Yeniden dene';retry.onclick=()=>RitimPremiumAPI.documentUpload(input,context,order,job);feedback.append(retry)}else toast(e.message)}finally{fields.forEach(f=>f.disabled=false)}},
