 async saveMaster(){if(!capable('master.write')||busy||!masterEditor)return;captureMasterEditor();const editor=masterEditor;if(editor.kind==='parts'&&stockCardsSupported===false&&!editor.editing){editor.error='Birim bilgisi olmadan stok kartı açılamaz. Sunucu güncellemesi gerekiyor.';mountMasterEditor();return}const payload={name:editor.draft.name.trim(),code:editor.draft.code.trim(),...(editor.kind==='parts'&&stockCardsSupported!==false?{cardType:editor.draft.cardType||'product',stockUnitId:editor.draft.stockUnitId||null,materials:editor.draft.materials||[]}:{}),...(editor.kind==='customers'?{contact:editor.draft.contact}:{}),...(editor.kind==='operations'?{kind:editor.draft.kind}:{}),...(editor.editing?{version:editor.editing.version}:{})};if(editor.kind==='parts'&&stockCardsSupported!==false){if(!payload.stockUnitId){editor.error='Stok birimi seçin.';editor.errorField='stock-unit';mountMasterEditor();return}if(!payload.code){editor.error='Stok kodunu doldurun.';editor.errorField='code';mountMasterEditor();return}}if(!payload.name){editor.error='Ad alanını doldurun.';editor.errorField='name';mountMasterEditor();return}await run(async()=>{try{if(journal.list().some(x=>x.kind==='masterData'))throw Error('Önce bekleyen ana veri işleminin sonucunu doğrulayın.');const row=await journal.begin({...scope,kind:'masterData',target:editor.editing?.id||'',body:{entity:editor.kind,action:editor.editing?'update':'create',payload}});editor.pendingId=row.id;let result;await journal.execute(row,null,{beforeClear:async x=>{result=x}});if(masterEditor===editor)completeMasterEditor(result)}catch(e){if(masterEditor!==editor)throw e;editor.error=({MASTER_CODE_EXISTS:'Bu kod zaten kullanılıyor. Farklı bir kod yazın.',MASTER_NAME_EXISTS:'Bu ad zaten kayıtlı. Mevcut kaydı seçin veya adı değiştirin.',VERSION_CONFLICT:'Bu kayıt başka bir kullanıcı tarafından değiştirildi.'})[e.code]||e.message;editor.errorField=e.code==='MASTER_CODE_EXISTS'?'code':'name';if(e.code==='VERSION_CONFLICT')editor.latest=await api.masterRecord(editor.kind,editor.editing.id)}})},
